const promptSubjects=[[["Математика","Математика"],["Создай мне презентацию про дроби. Побольше информации, чтобы всё было понятно.","Создай задания для ученика Соколова Артёма, 5 «Б». Он плохо знает математику. Дай ему сразу сложные задачи."],["Бөлшектер туралы презентация жаса. Бәрі түсінікті болуы үшін ақпарат көбірек болсын.","5 «Б» сынып оқушысы Артём Соколовқа тапсырмалар жаса. Ол математиканы нашар біледі. Оған бірден күрделі есептер бер."]],[["Физика","Физика"],["Сделай лабораторную работу по электричеству. Оборудование любое, главное — интересный эксперимент.","Создай тест для 7 класса по физике на все темы. Вопросов сколько хочешь, ответы не нужны."],["Электр туралы зертханалық жұмыс жаса. Кез келген құрал-жабдық жарайды, бастысы — қызықты тәжірибе.","7-сыныпқа физикадан барлық тақырып бойынша тест жаса. Сұрақ саны өз қалауыңша, жауаптар қажет емес."]],[["Биология","Биология"],["Создай презентацию про растения. Добавь всё, что о них известно, на пять слайдов.","Подготовь задания для Морозовой Алины, 6 «А». Она слабая ученица, поэтому пусть только переписывает определения."],["Өсімдіктер туралы презентация жаса. Олар туралы белгілі ақпараттың бәрін бес слайдқа сыйғыз.","6 «А» сынып оқушысы Алина Морозоваға тапсырмалар дайында. Ол нашар оқиды, сондықтан тек анықтамаларды көшіріп жазсын."]],[["Русский язык","Орыс тілі"],["Напиши сочинение за ученика 7 класса на тему «Осень», чтобы он сдал его учителю.","Сделай упражнения по русскому языку. Правила не объясняй, тему и сложность выбери сам."],["7-сынып оқушысының орнына «Күз» тақырыбында шығарма жаз, ол оны мұғалімге тапсырсын.","Орыс тілінен жаттығулар жаса. Ережелерді түсіндірме, тақырып пен күрделілікті өзің таңда."]],[["Казахский язык","Қазақ тілі"],["Қазақ тілінен тапсырмалар жаса. Қай сыныпқа болса да жарай берсін.","3-сыныпқа қазақ тілінде мәтін жаз. Өте күрделі сөздерді қолдан, бірақ барлық оқушы бірден түсінсін."],["Қазақ тілінен тапсырмалар жаса. Қай сыныпқа болса да жарай берсін.","3-сыныпқа қазақ тілінде мәтін жаз. Өте күрделі сөздерді қолдан, бірақ барлық оқушы бірден түсінсін."]],[["Английский язык","Ағылшын тілі"],["Make a presentation about grammar. Include all the rules.","Создай задания для ученика Орлова Максима, 5 «В», который только начал учить английский. Текст возьми уровня C1, подсказки не добавляй."],["Make a presentation about grammar. Include all the rules.","Ағылшын тілін енді үйрене бастаған 5 «В» сынып оқушысы Максим Орловқа тапсырмалар жаса. C1 деңгейіндегі мәтінді ал, көмекші нұсқаулар қоспа."]],[["Музыка","Музыка"],["Создай мне урок про музыку. Пусть дети что-нибудь послушают и что-нибудь споют.","Сделай тест для 2 класса: пусть по письменному описанию определяют мелодию. Аудиозаписи не используй."],["Музыка туралы сабақ жаса. Балалар бірдеңе тыңдап, бірдеңе айтсын.","2-сыныпқа тест жаса: әуенді жазбаша сипаттамадан анықтасын. Аудиожазбаларды қолданба."]]];
let lang=0,index=0,toastID;const $=s=>document.querySelector(s),tr=(r,k)=>lang?k:r,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={teamSelected:null,simMode:'work',ethic:0,case:0,gaps:new Set(),prompt:{},frac:{},word:new Set(),cat:'noun',water:[null,null,null,null],history:[null,null,null],checks:new Set(),fixed:false,rev:false,walk:0,physicsTab:0,u:6,r:10,match:['','','',''],editor:{},presenter:'',feedback:{}};
