function orderHTML(kind){const a=kind==='water'?waterLabels:histLabels,st=S[kind];return `<div class="order">${a.map((_,i)=>`<div><span>0${i+1}</span><label class="field">${kind==='water'?tr('Этап','Кезең'):['16.12.1991','04.06.1992','15.11.1993'][i]}<select data-order="${kind}" data-slot="${i}"><option value="">${tr('Выберите','Таңдаңыз')}</option>${[...a.keys()].reverse().map(j=>`<option value="${j}" ${st[i]===j?'selected':''}>${a[j][lang]}</option>`).join('')}</select></label></div>`).join('')}</div><div class="actions">${btn(tr('Проверить','Тексеру'),`ordercheck:${kind}`,'primary')}${btn(tr('Сначала','Қайта бастау'),`orderreset:${kind}`)}${kind==='history'?link('https://www.gov.kz/memleket/entities/mfa-kuala-lumpur/press/news/details/244973?lang=ru',tr('Официальный источник','Ресми дереккөз'),'fine'):''}</div><div class="feedback" id="orderFeedback" role="status"></div>`}
function physicsHTML(){if(S.physicsTab===1)return tabs()+`<div class="exercise"><h2>${tr('Язык: найти действие','Тіл: әрекетті табу')}</h2><p class="big-text">${tr('Ученик читает книгу.','Оқушы кітап оқиды.')}</p>${btn(tr('Читает','Оқиды'),'language-mini','primary')}</div>`;if(S.physicsTab===2)return tabs()+`<div class="flow"><div><b>01</b>${tr('Задать число 3','3 санын беру')}</div><div><b>02</b>${tr('Умножить на 2','2-ге көбейту')}</div><div><b>03</b>${tr('Прибавить 1','1 қосу')}</div></div>${btn(tr('Показать результат','Нәтижені көрсету'),'algorithm')}`;return tabs()+`<div class="split"><div class="controls"><label>${tr('Напряжение U','Кернеу U')}: <b id="uval">${S.u}</b> ${tr('В','В')}<input aria-label="U" id="voltage" type="range" min="1" max="12" value="${S.u}"></label><label>${tr('Сопротивление R','Кедергі R')}: <b id="rval">${S.r}</b> ${tr('Ом','Ом')}<input aria-label="R" id="resistance" type="range" min="1" max="20" value="${S.r}"></label>${btn(tr('Начальные значения','Бастапқы мәндер'),'physicsreset')}</div><div class="reading"><h2>I = U / R</h2><div class="metric" id="ival">${(S.u/S.r).toFixed(2).replace('.',',')} <span style="font-size:35px">A</span></div><p>${tr('Идеальный резистор','Идеал резистор')}</p></div></div>`}
function tabs(){return `<div class="tabs">${[tr('Физика','Физика'),tr('Языки','Тілдер'),tr('Информатика','Информатика')].map((x,i)=>btn(x,`physicstab:${i}`,S.physicsTab===i?'active':'')).join('')}</div>`}
function languageHTML(){return `<div class="tabs">${btn('Зат есім','cat:noun',S.cat==='noun'?'active':'')}${btn('Етістік','cat:verb',S.cat==='verb'?'active':'')}</div><div class="exercise"><p class="hint">${tr('Выберите все слова выбранной части речи.','Таңдалған сөз табына жататын барлық сөзді таңдаңыз.')}</p><div class="chipset" style="margin:20px 0">${['Бала','кітап','оқиды'].map((x,i)=>`<button class="word" data-action="word:${i}" aria-pressed="${S.word.has(i)}">${x}</button>`).join('')}</div><div class="actions">${btn(tr('Проверить','Тексеру'),'wordcheck','primary')}${btn(tr('Сначала','Қайта бастау'),'wordreset')}</div><div id="wordFeedback" class="feedback" role="status"></div></div>`}
const helpers=['Ustaz BilimAI Mektep','Tarbie BilimAI Mektep','Tarbieshi BilimAI Balabaksha','Canva'];
const tasks=[['Рабочий лист по КСП','ҚМЖ бойынша жұмыс парағы'],['Материалы классного часа','Сынып сағатының материалдары'],['План дня по циклограмме','Циклограмма бойынша күн жоспары'],['Дизайн презентации','Презентация дизайны']];
function matchHTML(){return `<div class="select-grid">${tasks.map((t,i)=>`<label class="field">0${i+1} ${t[lang]}<select data-match="${i}"><option value="">${tr('Выберите помощника','Көмекшіні таңдаңыз')}</option>${[3,1,0,2].map(j=>`<option value="${j}" ${S.match[i]===String(j)?'selected':''}>${helpers[j]}</option>`).join('')}</select></label>`).join('')}</div><div class="actions">${btn(tr('Проверить и объяснить','Тексеру және түсіндіру'),'matchcheck','primary')}</div>`}
function editorValues(){return S.editor[lang]||{q:tr('Чему равно 1/4 + 2/4?','1/4 + 2/4 қаншаға тең?'),answer:'3/4',why:tr('При одинаковом знаменателе складываем числители: (1 + 2) / 4 = 3/4.','Бөлімдері бірдей болса, алымдарын қосамыз: (1 + 2) / 4 = 3/4.')};}
function miniFile(){const e=editorValues(),texts=lang?{title:'Оқу тапсырмасы',label:'Жауап',check:'Тексеру',reset:'Қайта бастау',empty:'Алдымен жауап жазыңыз.',yes:'Дұрыс!',no:'Әзірге қате. Қайталап көріңіз.',rule:'Мысалы: 3/4. Ұпай бірінші жауапқа беріледі.',score:'Бірінші жауап ұпайы'}:{title:'Учебное задание',label:'Ответ',check:'Проверить',reset:'Сначала',empty:'Сначала введите ответ.',yes:'Верно!',no:'Пока неверно. Попробуйте ещё.',rule:'Например: 3/4. Балл за первый ответ.',score:'Балл за первый ответ'};const data=JSON.stringify({e,texts}).replace(/</g,'\\u003c');return `<!doctype html><html lang="${lang?'kk':'ru'}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${texts.title}</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0;padding:20px;background:#f8fafc;color:#0f172a}main{max-width:620px;margin:0 auto}h1{font-size:24px}input,button{font:inherit;border:1px solid #64748b;padding:10px;border-radius:8px;margin-top:8px;max-width:100%}input{width:100%}button{cursor:pointer;background:#0f172a;color:white}button:focus-visible,input:focus-visible{outline:3px solid #168bd2}p{line-height:1.5}small{color:#475569}</style><main><h1>${esc(e.q)}</h1><form><label for="answer">${texts.label}</label><input id="answer" autocomplete="off"><small>${texts.rule}</small><div><button type="submit">${texts.check}</button> <button type="button" id="reset">${texts.reset}</button></div></form><p id="feedback" role="status"></p><small id="score"></small></main><script>const {e,texts}=${data};let first=null;const a=document.getElementById('answer'),f=document.getElementById('feedback'),s=document.getElementById('score');const norm=v=>v.trim().toLocaleLowerCase().replace(/\\s+/g,'').replace(/,/g,'.');document.querySelector('form').onsubmit=ev=>{ev.preventDefault();if(!a.value.trim()){f.textContent=texts.empty;return}const good=norm(a.value)===norm(e.answer);if(first===null)first=good?1:0;f.textContent=(good?texts.yes:texts.no)+' '+e.why;s.textContent=texts.score+': '+first+' / 1'};document.getElementById('reset').onclick=()=>{first=null;a.value='';f.textContent='';s.textContent='';a.focus()};<\/script></html>`;}
function editorHTML(){let e=editorValues();return `<div class="editor"><form id="editorForm"><label class="field">${tr('Вопрос','Сұрақ')}<input data-edit="q" value="${esc(e.q)}" maxlength="160"></label><label class="field">${tr('Точный ответ','Дәл жауап')}<input data-edit="answer" value="${esc(e.answer)}" maxlength="80"></label><label class="field">${tr('Объяснение','Түсіндірме')}<textarea data-edit="why" maxlength="400">${esc(e.why)}</textarea></label><div class="actions">${btn(tr('Обновить','Жаңарту'),'preview','primary')}${btn(tr('Скачать HTML','HTML жүктеу'),'download')}${btn(tr('Промпт','Промпт'),'prompt:html','small-btn')}</div></form><div><div class="preview-title">${tr('Локальный шаблон · без генерации ИИ','Жергілікті үлгі · ЖИ генерациясынсыз')}</div><iframe id="preview" title="${tr('Предпросмотр задания','Тапсырма көрінісі')}" sandbox="allow-scripts allow-forms"></iframe></div></div>`}
const checkLabels=[['Содержание и ключ','Мазмұн мен кілт'],['Правильный ответ','Дұрыс жауап'],['Неверный ответ','Қате жауап'],['Пустой ввод','Бос жауап'],['Перезапуск и баллы','Қайта бастау мен ұпай'],['Читаемость и офлайн','Оқылымдылық пен офлайн']];
function checklistHTML(){return `<div class="checklist">${checkLabels.map((x,i)=>`<label><input type="checkbox" data-check="${i}" ${S.checks.has(i)?'checked':''}>${x[lang]}</label>`).join('')}</div><label class="field">${tr('Дефект или следующая доработка','Ақау немесе келесі түзету')}<input id="defect" value="${esc(S.defect||'')}" placeholder="${tr('Кнопка… Ожидали… Получили…','Батырма… Күтілгені… Нақтысы…')}"></label><div class="actions">${btn(tr('Открыть созданное задание','Жасалған тапсырманы ашу'),'testproduct')}${btn(tr('Запрос на исправление','Түзету сұранысы'),'fixprompt','primary')}</div>`}
function resourcesHTML(){return `<div class="resourcebox"><div><p class="hint">${tr('Материалы проекта','Жоба материалдары')}</p>${link('https://bilimai.kz/resources','bilimai.kz/resources','link-large')}<p class="fine">${tr('Внешняя ссылка: нужен интернет','Сыртқы сілтеме: интернет қажет')}</p></div><img class="qr" src="/*QRRES*/" alt="QR bilimai.kz/resources"></div><div class="actions">${btn(tr('Шаблон промпта','Промпт үлгісі'),'prompt:html')}${btn(tr('Редактор задания','Тапсырма редакторы'),'goto:39')}${btn(tr('Официальные источники','Ресми дереккөздер'),'sources')}</div>`}
const ustazShots=[["КТП", "КТЖ", "Учебная программа и цели", "Оқу бағдарламасы мен мақсаттар", "assets/plugin-import/media/7342adc79b46fe440ad0ee1a.png"], ["КСП / план урока", "ҚМЖ / сабақ жоспары", "Тема и учебные цели", "Тақырып пен оқу мақсаттары", "assets/plugin-import/media/c5631e456421dd68a1ed4ac3.png"], ["Презентация", "Презентация", "На основе готового КСП", "Дайын ҚМЖ негізінде", "assets/plugin-import/media/50db025759adc6d2fee14caa.png"], ["Рабочий лист", "Жұмыс парағы", "Задания по готовому КСП", "Дайын ҚМЖ бойынша тапсырмалар", "assets/plugin-import/media/b73000479f190aa6aa63f4cd.png"], ["ФО / СОР / СОЧ", "ҚБ / БЖБ / ТЖБ", "Цели и спецификация оценивания", "Мақсаттар мен бағалау спецификациясы", "assets/plugin-import/media/674bdca92652efdd43eff7e4.png"]];
function ustazOverview(){return `<p class="ustaz-definition">${tr("Плагин для учителей 1–11 классов, который помогает готовить планы, задания, оценивание и презентации на основе учебных целей и материалов педагога.","Мұғалімнің оқу мақсаттары мен материалдары негізінде жоспарлар, тапсырмалар, бағалау материалдары және презентациялар дайындауға көмектесетін 1–11 сынып мұғалімдеріне арналған плагин.")}</p><div class="ustaz-overview-layout"><button class="ustaz-quality" data-action="ustaz-shot:card" aria-label="${tr('Открыть карточку плагина','Плагин карточкасын ашу')}"><img src="assets/ustaz-card-quality.png" alt="Ustaz BilimAI Mektep — карточка плагина и навыки"></button><div class="ustaz-output-grid">${ustazShots.map((x,i)=>`<button class="ustaz-output" data-action="ustaz-shot:${i}"><strong>${x[lang]}</strong><span>${x[2+lang]}</span><img src="${x[4]}" alt="${x[lang]}"></button>`).join('')}</div></div>`;}
