function tarbieOverview(){return `<p class="ustaz-definition">${tr("Плагин для классных руководителей и заместителей по воспитательной работе, который помогает готовить планы, классные часы и материалы для родителей.","Тәрбие жоспарларын, сынып сағаттарын және ата-аналарға арналған материалдарды дайындауға көмектесетін сынып жетекшілері мен тәрбие ісі жөніндегі орынбасарларға арналған плагин.")}</p><div class="ustaz-overview-layout"><button class="ustaz-quality" data-action="tarbie-shot:card" aria-label="${tr('Открыть карточку Tarbie','Tarbie карточкасын ашу')}"><img src="assets/tarbie-card-quality.png" alt="Tarbie BilimAI Mektep — карточка плагина и навыки"></button><div class="ustaz-output-grid">${tarbieShots.map((x,i)=>`<button class="ustaz-output" data-action="tarbie-shot:${i}"><strong>${x[lang]}</strong><span>${x[2+lang]}</span><img src="${x[4]}" alt="${x[lang]}"></button>`).join('')}<div class="ustaz-basis"><p>${tr('Профилактика буллинга, социальные проекты и интеграция ценностей.','Буллингтің алдын алу, әлеуметтік жобалар және құндылықтарды кіріктіру.')}</p></div></div></div>`;}
const workGame={doc:0,condition:null,notes:'',checks:[false,false,false,false]};
const workChoices=[['Ustaz','Рабочий лист','3 задания по одной теме, ответы и дескрипторы'],['Ustaz','Фрагмент урока','Практическая часть на 15 минут с понятным результатом'],['Tarbie','Упражнение для классного часа','Задание на 10 минут и короткая рефлексия'],['Tarbie','Материалы для родителей','Приглашение на собрание и краткая памятка']];
