function showWorkshopPrompt(text){modal(tr('Ваш запрос для создания HTML','HTML жасауға арналған сұрауыңыз'),`<p>${tr('Скопируйте промпт в свой ChatGPT. Вставьте или приложите исходные материалы.','Промптты өз ChatGPT чатына көшіріңіз. Бастапқы материалдарды енгізіңіз немесе қосыңыз.')}</p><textarea id="hw-result" style="width:100%;height:360px;font:17px/1.5 Arial;padding:16px" aria-label="${tr('Готовый промпт','Дайын промпт')}">${esc(text)}</textarea><button id="hw-copy" class="primary" style="margin-top:12px">${tr('Скопировать промпт','Промптты көшіру')}</button>`);$('#hw-copy').onclick=()=>copy($('#hw-result').value);}


