function renderSocialContacts(){
$('#slide').className='slide social-contacts-slide';
$('#slide').innerHTML=`<div class="social-heading"><div><p class="social-eyebrow">BILIMAI · CHATGPT EDU</p><h1 id="slideTitle">${tr('Каналы связи BilimAI','BilimAI байланыс арналары')}</h1><p class="social-lead">${tr('Подписывайтесь, следите за новостями и оставайтесь на связи.','Жазылыңыз, жаңалықтарды бақылаңыз және байланыста болыңыз.')}</p></div><img src="assets/champions/image-2.png" alt="BilimAI" class="social-logo"></div><div class="social-grid">${getSocialContacts().map(a=>`<article class="social-card"><div class="social-card-top"><span class="social-icon" style="background:${a.color}" aria-hidden="true">${a.icon}</span><h2>${esc(a.name[lang])}</h2></div><div class="social-card-body"><div class="social-details"><a class="social-handle" href="${a.url}" target="_blank" rel="noopener noreferrer">${esc(a.handle)}</a><p>${esc(a.description[lang])}</p><a class="social-open" href="${a.url}" target="_blank" rel="noopener noreferrer">${tr('Открыть','Ашу')} ↗</a></div><a class="social-qr" href="${a.url}" target="_blank" rel="noopener noreferrer" aria-label="${esc(a.name[lang])} — QR">${a.qr}</a></div></article>`).join('')}</div><p class="social-footer">${tr('Наведите камеру на QR-код или нажмите на ссылку.','QR-кодқа камераны бағыттаңыз немесе сілтемені басыңыз.')}</p>`;
}

function renderTeacherFeedback(){
$('#slide').className='slide teacher-feedback-slide';
const url="https://docs.google.com/forms/d/e/1FAIpQLSchaV5hHSVebvD_IRWUE5XZDWPLVPCUUDfOCikoLDf3IRtUAQ/viewform?usp=header";
$('#slide').innerHTML=`<p class="feedback-eyebrow">USTAZ BILIMAI MEKTEP</p><h1 id="slideTitle">${tr('Обратная связь учителей','Мұғалімдердің кері байланысы')}</h1><div class="feedback-layout"><div class="feedback-copy"><h2>${tr('Уважаемые коллеги!','Құрметті әріптестер!')}</h2><p class="feedback-intro">${tr('Поделитесь впечатлениями о плагине Ustaz BilimAI Mektep. Ваш опыт поможет улучшить инструменты для учителей.','Ustaz BilimAI Mektep плагині туралы пікіріңізбен бөлісіңіз. Тәжірибеңіз мұғалімдерге арналған құралдарды жақсартуға көмектеседі.')}</p><ol><li>${tr('Отсканируйте QR-код камерой телефона.','Телефон камерасымен QR-кодты сканерлеңіз.')}</li><li>${tr('Откройте форму и оставьте обратную связь.','Форманы ашып, кері байланыс қалдырыңыз.')}</li></ol><a class="feedback-open" href="${url}" target="_blank" rel="noopener noreferrer">${tr('Открыть форму обратной связи','Кері байланыс формасын ашу')} ↗</a><p class="feedback-thanks">${tr('Спасибо за участие и ваши предложения!','Қатысқаныңызға және ұсыныстарыңызға рақмет!')}</p></div><a class="feedback-qr-card" href="${url}" target="_blank" rel="noopener noreferrer" aria-label="${tr('QR-код формы обратной связи','Кері байланыс формасының QR-коды')}"><img src="assets/teacher-feedback-qr.png" alt="${tr('QR-код для обратной связи учителей','Мұғалімдердің кері байланысына арналған QR-код')}"><span>${tr('Наведите камеру на QR-код','Камераны QR-кодқа бағыттаңыз')}</span></a></div>`;
}
